package com.bheemnagartimes.news.service;
import com.bheemnagartimes.news.model.NewsArticle;import com.openhtmltopdf.pdfboxout.PdfRendererBuilder;import org.springframework.stereotype.Service;import org.thymeleaf.TemplateEngine;import org.thymeleaf.context.Context;import java.io.*;
@Service public class PdfService{private final TemplateEngine engine;public PdfService(TemplateEngine e){engine=e;}public byte[] render(NewsArticle a,String brand,String tagline,String location,String slogan)throws IOException{Context c=new Context();c.setVariable("article",a);c.setVariable("brand",brand);c.setVariable("tagline",tagline);c.setVariable("location",location);c.setVariable("slogan",slogan);String html=engine.process("newspaper",c);try(ByteArrayOutputStream out=new ByteArrayOutputStream()){PdfRendererBuilder b=new PdfRendererBuilder();b.useFastMode();b.withHtmlContent(html,"http://localhost/");b.toStream(out);b.run();return out.toByteArray();}}}